import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CHX4lV2z.js";const u=JSON.parse('{"title":"Hook and Proxy Integration","description":"","frontmatter":{},"headers":[],"relativePath":"host-adapter-development/hook-proxy-integration.md","filePath":"host-adapter-development/hook-proxy-integration.md","lastUpdated":1791002220000}'),n={name:"host-adapter-development/hook-proxy-integration.md"};function i(s,e,d,l,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="hook-and-proxy-integration" tabindex="-1">Hook and Proxy Integration <a class="header-anchor" href="#hook-and-proxy-integration" aria-label="Permalink to &quot;Hook and Proxy Integration&quot;">​</a></h1><p>TokenPilot uses four integration patterns across its six host adapters: proxy + hooks, gateway + MCP, native plugin slot, and fully in-process extensions.</p><h2 id="integration-approaches" tabindex="-1">Integration Approaches <a class="header-anchor" href="#integration-approaches" aria-label="Permalink to &quot;Integration Approaches&quot;">​</a></h2><h3 id="proxy-hooks-codex-cli" tabindex="-1">Proxy + Hooks (Codex CLI) <a class="header-anchor" href="#proxy-hooks-codex-cli" aria-label="Permalink to &quot;Proxy + Hooks (Codex CLI)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: uses Codex config mutation, hook registration, and a local OpenAI-compatible Responses proxy. Preserves the current active Codex provider name and reroutes that provider&#39;s <code>base_url</code> through the local proxy. Hooks registered: <code>SessionStart</code>, <code>PreToolUse</code>, <code>PostToolUse</code>.</p><h3 id="gateway-mcp-sessionstart-claude-code" tabindex="-1">Gateway + MCP + SessionStart (Claude Code) <a class="header-anchor" href="#gateway-mcp-sessionstart-claude-code" aria-label="Permalink to &quot;Gateway + MCP + SessionStart (Claude Code)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: uses local Anthropic-compatible gateway routing plus lightweight hooks for observability. A <code>SessionStart</code> hook auto-starts the local gateway. The <code>tokenpilot_memory_fault_recover</code> MCP server is registered for recovery.</p><h3 id="native-plugin-slot-openclaw" tabindex="-1">Native Plugin Slot (OpenClaw) <a class="header-anchor" href="#native-plugin-slot-openclaw" aria-label="Permalink to &quot;Native Plugin Slot (OpenClaw)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: bundled plugin with embedded runtime. The host delivers events directly to the plugin without an external proxy or gateway. Supports in-host slash commands, lifecycle eviction controls, and <code>mode aggressive</code>.</p><h3 id="cordis-plugin-durable-projection-deepseek-harness" tabindex="-1">Cordis Plugin + Durable Projection (DeepSeek Harness) <a class="header-anchor" href="#cordis-plugin-durable-projection-deepseek-harness" aria-label="Permalink to &quot;Cordis Plugin + Durable Projection (DeepSeek Harness)&quot;">​</a></h3><p>From <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a>: a Cordis plugin adapter with durable session and event projection. Canonical-surface eviction is opt-in and guarded by estimator, registry, safety, and revision checks. Status is exposed through the native <code>/tokenpilot-status</code> command rather than the shared CLI.</p><h3 id="in-process-extension-pi" tabindex="-1">In-Process Extension (pi) <a class="header-anchor" href="#in-process-extension-pi" aria-label="Permalink to &quot;In-Process Extension (pi)&quot;">​</a></h3><p>pi has an in-process extension API, so no proxy or gateway is involved and no pi-owned config file is changed. The adapter registers <code>before_agent_start</code> for the stable prefix, <code>context</code> for request-time reduction, and <code>turn_end</code> for opt-in eviction through native <code>context_edit</code> entries. Because pi has no MCP, recovery is exposed as a native <code>memory_fault_recover</code> tool with the shared tool&#39;s name, description, and schema.</p><h3 id="in-process-plugin-mcp-opencode" tabindex="-1">In-Process Plugin + MCP (OpenCode) <a class="header-anchor" href="#in-process-plugin-mcp-opencode" aria-label="Permalink to &quot;In-Process Plugin + MCP (OpenCode)&quot;">​</a></h3><p>OpenCode loads the adapter as an in-process v1 plugin and takes the shared recovery MCP server from <code>opencode.json</code>. The plugin uses <code>experimental.chat.system.transform</code> for the stable prefix and <code>experimental.chat.messages.transform</code> for reduction and opt-in eviction, which runs before every model step. Evictions are stored per session as a durable overlay and re-applied identically on each request.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./adapter-architecture">Adapter Architecture</a></li><li><a href="./adding-new-host">Adding a New Host</a></li><li><a href="./configuration-integration">Configuration Integration</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/HOSTS.md" target="_blank" rel="noreferrer">HOSTS.md</a></li></ul>',17)])])}const g=o(n,[["render",i]]);export{u as __pageData,g as default};
